export interface CliState {
	result?: unknown;
	error?: unknown;
}

export interface CliRuntimeContext extends CommandContext {
	readonly process: StricliProcess;
	client?: HevyClient;
	operations?: HevyOperations;
	execution?: HevyExecutionOptions;
	now: () => Date;
	readDataSource: DataSourceReader;
